docHref.source:
function docHref(d){
 if (SYNC.backend && SYNC.backend.fileUrl) {
 const f = DOCS.files && DOCS.files[d.id];
 return f ? SYNC.backend.fileUrl(d.id) : null;
 }
 return d.href || null;
}

docAvailability.source:
function docAvailability(d){
 const hosted = !!(SYNC.backend && SYNC.backend.fileUrl), href = docHref(d);
 if (!hosted) return {state: href ? 'ready' : 'missing', href: href, label: href ? 'Beside this file' : 'Not beside this file', tone: href ? 'good' : 'gap'};
 if (DOCS.state === 'unrequested' || DOCS.state === 'loading') return {state: 'checking', href: href, label: 'Checking availability', tone: 'plan'};
 if (DOCS.state !== 'ready') return {state: 'unchecked', href: href, label: 'Unable to check availability', tone: 'warn'};
 return {state: href ? 'ready' : 'missing', href: href, label: href ? 'Available' : 'Not hosted', tone: href ? 'good' : 'gap'};
}

docPhotoPreview.source:
function docPhotoPreview(d, href){
 const safe = value => {
 if (typeof value !== 'string' || !value.trim()) return false;
 if (/^data:/i.test(value.trim())) return /^data:image\/(?:jpeg|png|webp|gif|bmp);base64,/i.test(value.trim());
 try { return ['https:', 'http:'].includes(new URL(value, 'https://gc500.invalid/').protocol); }
 catch (e) { return false; }
 };
 if (typeof d.thumb === 'string' && safe(d.thumb)) return d.thumb;
 const f = DOCS.files && DOCS.files[d.id];
 if (f && f.thumb === true && SYNC.backend && SYNC.backend.thumbUrl)
 return SYNC.backend.thumbUrl(d.id, f.sha256);
 // A missing derivative is not permission to download the original into a small card.
 return null;
}

docCatOf.source:
function docCatOf(d){
 if (d.kind === 'invoice' || d.group === 'invoices') return 'Invoices';
 if (d.group === 'dropphotos' || d.kind === 'photo') return 'Photographs';
 if (d.kind === 'docket' || d.group === 'dockets') return 'Fencing dockets';
 if (d.kind === 'swms') return 'SWMS & safety plan';
 if (d.kind === 'transport') return 'Transport & lifting';
 if (d.kind === 'pack') return 'Packs';
 return 'Maps and drawings';
}

docCollection.source:
function docCollection(){
 const hosted = !!(SYNC.backend && SYNC.backend.fileUrl);
 const reg = DATA.docs || {docs: [], counts: {}};
 const known = new Set(reg.docs.map(d => d.id));
 const extra = hosted && DOCS.files ? Object.values(DOCS.files).filter(f => !known.has(f.id)).map(f => {
 const nm = String(f.name || '');
 const isDrop = f.kind === 'drop-photo' || isDropPhotoName(nm) || isDropPhotoName(f.id);
 /* Filed deliberately, against something: a photograph of a location carries its reference, an invoice its
 branch. Those two say what they are on their card and no rule below second-guesses them — a photograph of
 P09 named 36503.jpg is a photograph of P09, not a docket, because a person said so when it went up. */
 const explicit = f.kind === 'photo' ? 'photo' : f.kind === 'invoice' ? 'invoice' : null;
 /* An uploaded picture that is not a drop photograph is still a photograph — a site picture somebody took
 and sent up. It used to be filed as a drawing source, so six phone pictures appeared among the plates. */
 const isPhoto = explicit === 'photo' || isDrop || (!explicit && DOC_IMG.test(nm) && f.kind !== 'map' && f.kind !== 'pack');
 /* A PAPER NAMED AFTER A DOCKET IS A DOCKET, WHATEVER BOX WAS TICKED WHEN IT WENT UP. The upload form's Kind
 is filing; the number in the name is evidence, and the two disagreeing should never put a signed paper in
 the wrong drawer. The library files it under Fencing dockets and its note says how it was actually filed,
 so the record can be tidied without the page pretending it already is. */
 const dkNo = f.kind === 'docket' || explicit ? null : docketNoInName(nm) || docketNoInName(String(f.title || ''));
 const isDocket = f.kind === 'docket' || !!dkNo;
 return {
 id: f.id,
 kind: isDocket ? 'docket' : explicit === 'invoice' ? 'invoice' : f.kind === 'swms' ? 'swms' : f.kind === 'transport' ? 'transport' : f.kind === 'pack' ? 'pack'
 : isPhoto ? 'photo' : 'map',
 group: isDocket ? 'dockets' : explicit === 'invoice' ? 'invoices' : f.kind === 'swms' ? 'swms' : f.kind === 'transport' ? 'transport' : f.kind === 'pack' ? 'packs'
 : isDrop ? 'dropphotos' : isPhoto ? 'photos' : 'uploaded',
 title: f.title || nm.replace(/[.][A-Za-z0-9]+$/, '').replace(/_+/g, ' ').trim() || nm, name: nm, bytes: f.bytes, ext: (nm.split('.').pop() || '').toLowerCase(),
 ref: f.ref || null, branch: f.branch || null, invoice_no: f.invoice_no || null,
 note: (f.note || null) || (dkNo ? 'Fencing docket ' + dkNo + ', matched by the number in its file name. It was uploaded under "'
 + (f.kind || 'other') + '" rather than Fencing docket — the paper is right, the filing is not.' : null),
 thumb: f.thumb === true, _up: f, source: 'uploaded', drop: isDrop};
 }) : [];
 const items = reg.docs.map(d => Object.assign({}, d, {source: 'catalogue', drop: false}))
.concat(extra)
.map(d => {
 const availability = docAvailability(d);
 return Object.assign(d, {category: docCatOf(d), availability: availability.state, available: availability.state === 'ready'});
 });
 const byCategory = {};
 DOC_CATS.forEach(c => { byCategory[c] = 0; });
 items.forEach(d => { byCategory[d.category] = (byCategory[d.category] || 0) + 1; });
 const available = items.filter(d => d.available).length;
 return {
 hosted: hosted, items: items,
 /* the three scopes, each named, so a number can never be read over the wrong set */
 catalogue: items.filter(d => d.source === 'catalogue').length,
 uploaded: items.filter(d => d.source === 'uploaded').length,
 photos: items.filter(d => d.category === 'Photographs').length,
 available: available, unhosted: items.filter(d => d.availability === 'missing').length,
 checking: items.filter(d => d.availability === 'checking').length,
 unchecked: items.filter(d => d.availability === 'unchecked').length,
 availabilityState: !hosted || DOCS.state === 'ready' ? 'ready' : DOCS.state === 'loading' || DOCS.state === 'unrequested' ? 'checking' : 'unchecked',
 byCategory: byCategory,
 countOf: function(kind){ return items.filter(d => d.kind === kind).length; },
 };
}

docCard.source:
function docCard(d, uploaded){
 const href = docHref(d);
 const hosted = !!(SYNC.backend && SYNC.backend.fileUrl);
 const kind = d.kind === 'invoice' || d.group === 'invoices' ? 'invoice' : d.kind === 'photo' || d.group === 'photos' || d.group === 'dropphotos' ? 'photo' : d.kind === 'docket' || d.group === 'dockets' ? 'docket' : d.kind === 'swms' ? 'swms' : d.kind === 'transport' ? 'transport' : d.kind === 'pack' ? 'pack' : 'map';
 const meta = [];
 if (kind === 'swms') { const ty = docTypeOf(d); meta.push(esc(ty.words) + (ty.from ? ' — ' + esc(ty.from) : '')); }
 /* what it is filed against — said on the card, and the reference is a button that opens the thing itself */
 if (d.ref) meta.push('filed against <button type="button" class="linkish" data-open="' + esc(d.ref) + '">' + esc(d.ref) + '</button>');
 if (d.branch) meta.push('branch <b>' + esc(d.branch) + '</b>' + (branchName(d.branch) ? ' — ' + esc(branchName(d.branch)) : ''));
 if (d.invoice_no) meta.push('invoice no. <b>' + esc(d.invoice_no) + '</b>');
 if (d.doc_ref) meta.push('<b>' + esc(d.doc_ref) + '</b>');
 if (d.sheet_ids && d.sheet_ids.length === 1) meta.push(`<b>${esc(d.sheet_ids[0])}</b>`);
 if (d.revision) meta.push('rev ' + esc(d.revision));
 if (d.rev_on_page) meta.push('rev ' + esc(d.rev_on_page) + ' on page 1');
 if (d.date_on_page) meta.push(esc(d.date_on_page) + ' on page 1');
 if (d.paper) meta.push(esc(d.paper) + (d.orientation === 'portrait' && d.paper !== '16:9 slide' ? ' portrait' : ''));
 if (d.pages) meta.push(d.pages + (d.pages === 1 ? ' page' : ' pages'));
 if (d.bytes) meta.push(fmtBytes(d.bytes));
 if (d.ext && d.ext !== 'pdf') meta.push(esc(d.ext.toUpperCase()));
 if (d.title_from === 'file name') meta.push('title is the file name');
 if (uploaded) meta.push((uploaded.uploaded ? 'uploaded ' + esc(fmtStamp(uploaded.uploaded)) : 'upload time not recorded') + (uploaded.by ? ' by ' + esc(uploaded.by) : ''));
 const sheets = d.sheets && d.sheets.length > 1 ? `<ul class="docsheets">${d.sheets.map(x => `<li><b>${esc(x.sheet_id)}</b> ${esc(x.title)}${x.year && x.year !== 2026 ? ' <span class="chip cand">' + x.year + '</span>' : ''}</li>`).join('')}</ul>` : '';
 const portrait = d.orientation === 'portrait';
 const preview = kind === 'photo' ? docPhotoPreview(d, href) : null;
 const image = preview ? `<span class="docpreview-shell"><span class="docpreview-status" role="status">Loading preview…</span><img class="thumb" src="${esc(preview)}" alt="${esc(d.title || d.name || 'Site photograph')}" loading="lazy" decoding="async" data-photo-preview data-dphopen="${esc(href || '')}"></span>` : '';
 const thumb = kind === 'photo'
 ? (image ? (href ? `<a class="docphoto-link" href="${esc(href)}" target="_blank" rel="noopener" aria-label="Open original photograph: ${esc(d.title || d.name || '')}">${image}</a>` : image)
 : `<div class="thumb none docpreview-fallback">${href ? 'Preview not made yet — open the original.' : 'Photograph preview not available.'}</div>`)
 : typeof d.thumb === 'string' && d.thumb ? `<img class="thumb${portrait ? ' portrait' : ''}" src="${d.thumb}" alt="" ${href ? `data-open="${esc(href)}"` : ''} loading="lazy">`
 : `<div class="thumb none">${esc((d.ext || '').toUpperCase() || 'file')}</div>`;
 const openBtn = href ? `<a class="btn primary" href="${esc(href)}" target="_blank" rel="noopener">${kind === 'photo' ? 'Open original' : 'Open' + (d.ext === 'pdf' ? ' PDF' : '')}</a>` : '';
 const printBtn = d.map_key && DATA.sheets.some(s => s.key === d.map_key) ? `<button class="btn" data-printsheet="${esc(d.map_key)}">Print sheet</button>` : '';
 const availability = docAvailability(d);
 const absent = hosted && availability.state !== 'ready' ? `<span class="absent">${availability.state === 'checking'
 ? 'Checking the service. File availability is not confirmed yet.' : availability.state === 'unchecked'
 ? 'The service could not be checked. This does not establish that the file is missing.'
 : 'Not on the service yet — upload it on the admin page, or here with the edit link.'}</span>` : '';
 const local = !hosted && href ? `<span class="meta">Opens from the package folder beside this file.</span>` : '';
 const del = uploaded && hosted && !SYNC.readonly ? `<button class="btn" data-delfile="${esc(d.id)}" title="Remove this file from the service">Remove</button>` : '';
 /* Board 3, "the document hub": one card shell. The kind on an orange tab at the top-left, the slashes at the
 top-right, the cover on the left, the title and what it is on the right, then two pills that never lie —
 whether the file is actually there, and what kind of source it is — the revision line, and one orange
 action. Availability is a fact about the service, never about approval, and the card says which. */
 const KIND_LABEL = {swms: 'SWMS', transport: 'Transport', map: 'Drawing', pack: 'Pack', photo: 'Photo', docket: 'Docket', invoice: 'Invoice'};
 const avail = [availability.tone, availability.label];
 const source = kind === 'invoice' ? 'Supplier invoice' + (d.branch ? ' · ' + esc(d.branch) : '') : kind === 'photo' ? (d.ref ? 'Photograph of ' + esc(d.ref) : 'Site photograph') : kind === 'docket' ? 'Signed on site' : kind === 'map' ? 'Drawing source' : kind === 'swms' ? 'Source document' : kind === 'transport' ? 'Coates procedure' : uploaded ? 'Uploaded to the service' : 'Made by this page';
 const rev = [];
 if (d.revision) rev.push('rev ' + esc(d.revision));
 if (d.rev_on_page) rev.push('rev ' + esc(d.rev_on_page) + ' on page 1');
 if (d.date_on_page) rev.push(esc(d.date_on_page));
 if (uploaded) rev.push((uploaded.uploaded ? 'uploaded ' + esc(fmtStamp(uploaded.uploaded)) : 'upload time not recorded') + (uploaded.by ? ' by ' + esc(uploaded.by) : ''));
 if (kind === 'photo') {
 const captured = d.capturedAt || d.captured_at || (uploaded && (uploaded.capturedAt || uploaded.captured_at));
 rev.push(captured ? 'captured ' + esc(fmtStamp(captured)) : 'capture time not recorded');
 }
 const subline = [d.doc_ref ? esc(d.doc_ref) : '', d.sheet_ids && d.sheet_ids.length === 1 ? esc(d.sheet_ids[0]) : '',
 d.pages ? d.pages + (d.pages === 1 ? ' page' : ' pages') : '', d.paper ? esc(d.paper) : ''].filter(Boolean).join(' · ');
 return `<div class="cut doccard ${kind}${href ? '' : ' offsvc'}" data-doc="${esc(d.id)}"><span class="face">
 <span class="dockind">${kind === 'swms' ? esc(docTypeOf(d).label) : KIND_LABEL[kind]}</span><span class="slash doc" aria-hidden="true">//</span>
 <div class="docbody">
 <div class="doccover${portrait ? ' portrait' : ''}">${thumb}</div>
 <div class="docmain">
 <h4>${esc(d.title)}</h4>
 ${subline ? `<div class="docsub">${subline}</div>` : ''}
 <div class="docpills"><span class="pill ${avail[0]}"><i class="pipdot" aria-hidden="true"></i>${avail[1]}</span><span class="pill plan">${source}</span></div>
 <div class="docrev"><b>${kind === 'photo' ? 'Photo details' : kind === 'invoice' ? 'Invoice details' : kind === 'docket' ? 'Docket details' : rev.length ? 'Revision details' : 'Revision'}</b><span>${rev.length ? rev.join(' · ') : 'no revision recorded on the file'}</span></div>
 <div class="acts">${openBtn}${printBtn}${del}${(meta.length || d.note || sheets) ? `<button type="button" class="btn ghost" data-docmore="${esc(d.id)}" aria-expanded="false">Details</button>` : ''}</div>
 ${absent}${local}
 </div>
 </div>
 <div class="docmore" hidden>
 <div class="meta">${meta.join(' · ')}</div>
 ${d.note ? `<div class="note">${esc(d.note)}</div>` : ''}
 ${sheets}
 </div>
 </span></div>`;
}

finderPick.source:
function finderPick(i){
 const it = (FINDER.list || [])[i]; if (!it) return;
 finderClose();
 state.q = ''; const qb = $('#q'); if (qb) { qb.value = ''; qb.blur(); } $('#qx').hidden = true; document.body.classList.remove('search-open');
 /* v5.79 — a reference or an asset number goes to WHERE IT IS: the sheet it is drawn on, zoomed on its pill, a ring
 round it. Its record is one press away on the strip above the map. A reference
 with no place on any drawing still opens its record, and says so. */
 if (it.kind === 'asset') { const a = assetOf(it.key), at = a && mapPlaceFor(a);
 if (at) { mapLocate(at.sheet.key, at.label, it.key, {marker: at.marker}); return; }
 render(); openAsset(it.key); flash(it.key + ' has no place on a drawing, so its record is open instead.'); return; }
 if (it.kind === 'unit') { state.unit = it.label || null;
 const u = allUnits().find(x => x.ref === it.key && (x.label || '') === (it.label || '') && (x.asset_no || '') === (it.no || ''));
 const at = unitPlaceFor(u) || (assetOf(it.key) && mapPlaceFor(assetOf(it.key)));
 if (at) { mapLocate(at.sheet.key, at.label, it.key, {marker: at.marker, unit: unitPlaceFor(u) ? (it.label || null) : null}); return; }
 render(); openAsset(it.key); flash((it.label || 'asset ' + it.no) + ' has no place on a drawing, so the record of ' + it.key + ' is open instead.'); return; }
 if (it.kind === 'place') { mapLocate(it.sheetKey, it.label); return; }
 if (it.kind === 'sheet') { state.sheet = it.sheetKey; state.sel = null; state.zoom = 1; state.ox = 0; state.oy = 0; go('map'); return; }
 /* v5.63 — a document opens if the service holds it, and a DAY of a per-day document opens at that day's
 page. Where the file is not on the service there is nothing to open, so the page it is listed on is the
 honest destination rather than a dead link. */
 if (it.kind === 'doc' || it.kind === 'docday') {
 const href = docHref({id: it.id});
 if (href) { window.open(it.kind === 'docday' ? href + '#page=' + it.page : href, '_blank', 'noopener'); return; }
 go('docs'); return;
 }
}

finderIndex.source:
function finderIndex(){
 const out = [];
 allAssets().forEach(a => {
 const nums = assetNumbersOf(a), links = a.drawing_links || [], units = unitsOf(a.key);
 out.push({kind: 'asset', key: a.key, name: a.name || '', type: (a.item_types || []).join(', ') || a.product || '', nums, links, disc: a.discipline,
 hay: [a.key, a.name, a.product,...(a.item_types || []),...nums,...links.map(l => l.label),...links.map(l => l.sheet),...(a.locations || []), a.discipline,
...units.map(u => u.asset_no),...units.map(u => u.label)]
.filter(Boolean).join(' ').toLowerCase()});
 });
 allUnits().forEach(u => out.push({kind: 'unit', key: u.ref, label: u.label || '', no: u.asset_no || '', sheet: u.sheet || '', callout: u.callout || '',
 hay: [u.label, u.asset_no, u.callout, u.sheet, u.ref].filter(Boolean).join(' ').toLowerCase()}));
 DATA.sheets.forEach(sh => {
 out.push({kind: 'sheet', sheetKey: sh.key, sheetId: sh.sheet_id || sh.key, title: sh.title || sh.key, sub: sh.subtitle || '',
 hay: [sh.key, sh.sheet_id, sh.title, sh.subtitle].filter(Boolean).join(' ').toLowerCase()});
 (sh.markers || []).forEach(m => { if (m.marker_kind === 'note' || !m.label) return;
 out.push({kind: 'place', sheetKey: sh.key, sheetId: sh.sheet_id || sh.key, title: sh.title || sh.key, label: String(m.label), tag: m.tag || '',
 hay: ('callout ' + m.label + ' ' + sh.sheet_id + ' ' + sh.key + ' ' + sh.title + ' ' + (m.tag || '')).toLowerCase()}); });
 });
 /* v5.63 — DOCUMENTS WERE NOT IN HERE AT ALL. The finder indexed assets, units, places and drawing sheets,
 so typing "pre-start", "SWMS" or "HSEQ" matched nothing and the only route to a document was to open
 Documents and go looking. Every document the register lists is now findable by its own words.
 A document that is one page a day also gets an entry PER DAY, because one page a day is only worth
 having if somebody can reach today's page — on a phone, at six in the morning, without scrolling
 sixty-eight pages to find it. Typing a date lands on that date. */
 ((DATA.docs || {}).docs || []).forEach(dc => {
 const title = dc.title || dc.name || dc.id;
 out.push({kind: 'doc', id: dc.id, title, docKind: dc.kind || '', pages: dc.pages || 0, ext: dc.ext || '',
 hay: [title, dc.name, dc.id, dc.kind, dc.doc_type, dc.note, dc.doc_ref].filter(Boolean).join(' ').toLowerCase()});
 (dc.days || []).forEach(dy => out.push({kind: 'docday', id: dc.id, title, page: dy.page, date: dy.date,
 display: dy.display || dy.date, basis: dy.basis || '',
 hay: [dy.display, dy.date, title, 'pre start prestart'].filter(Boolean).join(' ').toLowerCase()}));
 });
 return out;
}

planUpdateCardBefore803.source:
function planUpdateCardBefore803(u){
 const fq = (fields) => Object.entries(fields || {}).map(([k, v]) => { const c = FCOL.find(x => x.programme_type === k); return `${esc(fmtQty(v, c ? c.unit : ''))} ${esc(c ? c.name_as_written : k)}`; }).join(', ') || '—';
 const kind = k => k === 'changed' ? '<span class="chip act">changed</span>' : k === 'only in the programme' ? '<span class="chip cand">in the programme, not in the plan</span>' : k === 'only in the plan' ? '<span class="chip cand">in the plan, not in the programme</span>' : `<span class="chip">${esc(k)}</span>`;
 return `<div class="planupd"><h3>${esc(u.title)} — the update, ${esc(u.created_display)}</h3>
 <p class="sub">${esc(u.basis)} ${u.days_covered.length ? `Days covered: ${u.days_covered.map(d => esc(fmtDate(d).slice(0, 10))).join(', ')}.` : ''} <button class="linkish" data-go="docs">Open the plan on the Documents tab</button></p>
 ${u.differences.length ? `<div class="sect">Against the programme workbook — ${u.differences.length} difference${u.differences.length === 1 ? '' : 's'}</div>
 <div class="tblwrap"><table class="daytbl"><thead><tr><th>Day</th><th>Line</th><th>Programme said</th><th>The plan says</th><th></th></tr></thead><tbody>${
 u.differences.map(x => `<tr><td style="white-space:nowrap">${esc(fmtDate(x.date).slice(0, 10))}</td><td><b>${esc(x.location)}</b><br><span class="w">${esc(x.description || '')}</span>${x.comment ? `<br><span class="w" style="color:var(--mute)">workbook comment: ${esc(x.comment)}</span>` : ''}</td>
 <td>${x.programme ? fq(x.programme) : '<span class="todo">—</span>'}</td><td>${x.plan ? fq(x.plan) : '<span class="todo">not on the plan</span>'}${x.flag ? `<br><span class="w" style="color:var(--mute)">${esc(x.flag)}</span>` : ''}</td><td>${kind(x.kind)}</td></tr>`).join('')}</tbody></table></div>` : '<p class="sub">Every figure matches the programme workbook.</p>'}
 ${u.flags.length ? `<div class="sect">What the plan flags on its own pages</div><ul class="hublist compact">${u.flags.map(f => `<li><span class="tm">${esc(fmtDate(f.date).slice(0, 6))}</span><b>${esc(f.location)}</b> · ${esc(f.description)} <span class="w" style="color:var(--mute)">— ${esc(f.flag)}${f.page ? ' (p. ' + f.page + ')' : ''}</span></li>`).join('')}</ul>` : ''}
 ${u.notes.length ? `<div class="sect">Notes on the plan's pages</div><ul class="hublist compact">${u.notes.map(n => `<li><span class="tm">${esc(fmtDate(n.date).slice(0, 6))}</span>${esc(n.text)} <span class="w" style="color:var(--mute)">(p. ${n.page})</span></li>`).join('')}</ul>` : ''}
 <p class="norate">Nothing here is resolved by the page: a changed figure is shown with both values, a line the plan drops stays listed, and the plan's own flags are carried as written. The transcript is checked against the PDF's text; the PDF is the document.</p>
 </div>`;
}
